'use strict';
const LiveActivityPanel = (() => {
 let current = null;
 let blobUrls = [];
 const $ = id => document.getElementById(id);
 const labels = {waiting:'Waiting for context',queued:'Context ready · waiting for its turn',generating:'Generating response',validating:'Validating response',submitted:'Response submitted',stalled:'Stalled submission',interrupted:'Request interrupted',not_started:'Did not start'};
 const eventLabels = {batch_started:'Batch started',model_metadata:'Model verified',run_started:'Task run started',agent_observation:'Context recorded',generation_started:'Model request started',generation_result:'Model response received',task_update:'Answer submitted',communication_delivery:'Peer history delivered',communication_unlocked:'Communication unlocked',checkpoint_committed:'Checkpoint committed',minute_violation:'Deadline or submission violation',run_error:'Run error',run_finished:'Task run finished',batch_finished:'Batch finished',stop_requested:'Stop requested',researcher_action:'Researcher action'};
 function node(tag, className, text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
 function duration(seconds){const s=Math.max(0,Math.floor(seconds));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
 function responseCard(update){const card=node('article','live-response');const heading=node('div','live-response-heading',`Checkpoint ${update.step+1}`);heading.append(node('time','',new Date(update.timestamp).toLocaleTimeString()));card.append(heading,node('p','',update.response_text||`No answer generated: ${update.done_reason||'stalled'}`));const meta=[];if(update.answer_class!=null)meta.push(`Answer: ${update.answer_class}`);if(update.evaluator)meta.push(`Score: ${update.evaluator.score}`);meta.push(`${update.visible_message_ids?.length||0} peer updates delivered`);if(typeof update.latency_ms==='number')meta.push(`${(update.latency_ms/1000).toFixed(1)}s request`);card.append(node('p','live-response-meta',meta.join(' · ')));const source=node('details','live-source');source.append(node('summary','','Source update'),node('pre','',JSON.stringify(update,null,2)));card.append(source);return card;}
 function renderAgent(agent, record){const host=$('live-agent-'+agent);host.replaceChildren();const status=node('div','agent-activity-state '+record.state);status.id='live-state-'+agent;status.textContent=labels[record.state]||record.state;host.append(status);if(record.observation){const availability=record.observation.communication_available;host.append(node('p','live-response-meta',`${availability?'Peer channel open':'Isolated context'} · checkpoint ${record.observation.step+1}`));const context=node('details','live-context');context.append(node('summary','','Exact supplied context'),node('pre','',JSON.stringify(record.observation.messages,null,2)));host.append(context);}const transcript=node('div','live-transcript');for(const update of record.updates)transcript.append(responseCard(update));if(!record.updates.length)transcript.append(node('p','live-empty','No response submitted yet.'));host.append(transcript);}
 function render(data, live){const activity=data.live_activity;current={data,live};const header=$('live-header-summary');if(!activity){header.textContent=live?'Restart the panel to enable live activity.':'This older snapshot has no activity projection. Use Run inspector to browse its logs.';for(const id of ['download-completed-bundle','download-completed-responses'])$(id).hidden=true;return;}
  const run=activity.run;header.textContent=run?`${activity.batch_status.replaceAll('_',' ')} · ${run.task?.title||run.task_id} · ${run.condition_id} · repeat ${(run.repeat??0)+1} · checkpoint ${activity.step==null?'pending':activity.step+1}`:activity.batch_status==='running'?'Starting batch · waiting for model metadata':'No task run selected.';
  const count=(data.events||[]).filter(e=>e.kind==='task_update').length;const expected=data.batch?.config?.expected_updates;const progress=$('live-progress');progress.max=expected||Math.max(count,1);progress.value=count;$('live-batch-progress').textContent=`${count}${expected?' / '+expected:''} batch updates recorded`;
  for(const agent of ['A','B'])renderAgent(agent,activity.agents[agent]);
  const shared=$('live-shared-history');shared.replaceChildren();const available=Object.values(activity.agents).some(a=>a.observation?.communication_available);shared.append(node('div','shared-state',available?'Peer channel open':'Peer channel closed'));
  for(const message of activity.shared_history){const card=node('article','live-response');card.append(node('strong','',`Agent ${message.agent_id} · checkpoint ${message.step+1}`),node('p','',message.response_text||'Stalled update'),node('small','',`Delivered to ${message.visible_to.join(', ')} · ${message.event_id}`));shared.append(card);}if(!activity.shared_history.length)shared.append(node('p','live-empty',available?'No previous peer updates delivered yet.':'Agents cannot see each other’s history here.'));
  const feed=$('live-event-feed');feed.replaceChildren();for(const event of [...activity.feed].reverse()){const row=node('div','live-feed-row');row.append(node('time','',new Date(event.timestamp).toLocaleTimeString()),node('strong','',eventLabels[event.kind]||event.kind.replaceAll('_',' ')),node('span','',`${event.agent_id?'Agent '+event.agent_id:''}${event.step==null?'':' · checkpoint '+(event.step+1)}`));if(event.detail)row.append(node('span','',event.detail));row.title=event.event_id;feed.append(row);}
  for(const url of blobUrls)URL.revokeObjectURL(url);blobUrls=[];
  for(const [id,url] of [['download-completed-bundle',activity.exports.bundle_url],['download-completed-responses',activity.exports.responses_url]]){const link=$(id);link.hidden=!activity.exports.ready;if(live&&url){link.href=url;link.removeAttribute('download');}else if(activity.exports.ready){let text,name,type;if(id==='download-completed-bundle'){text=JSON.stringify(data,null,2);name='apart-research-snapshot.json';type='application/json';link.textContent='↓ Download batch snapshot · JSON';}else{const observations=new Map(data.events.filter(e=>e.kind==='agent_observation').map(e=>[e.event_id,e.payload]));text=data.events.filter(e=>e.kind==='task_update').map(e=>JSON.stringify({...e.payload,event_id:e.event_id,timestamp:e.timestamp,observation:observations.get(e.payload.observation_id)||null})).join('\n')+'\n';name='responses.jsonl';type='application/x-ndjson';}const blobUrl=URL.createObjectURL(new Blob([text],{type}));blobUrls.push(blobUrl);link.href=blobUrl;link.download=name;}else link.removeAttribute('href');}
  tick();
 }
 function tick(){if(!current?.data.live_activity)return;const {data}=current;const activity=data.live_activity;const started=Date.parse(activity.run_started_at);const ended=Date.parse(activity.run_finished_at);const now=Date.now();$('live-run-clock').textContent=Number.isFinite(started)?`Task run time ${duration(((Number.isFinite(ended)?ended:now)-started)/1000)} · ${duration(data.batch?.config?.deadline_seconds||300)} budget`:'';const last=Date.parse(activity.last_event_at);$('live-last-event').textContent=Number.isFinite(last)?`Last recorded event ${Math.max(0,Math.floor((now-last)/1000))}s ago`:'';for(const agent of ['A','B']){const record=activity.agents[agent];if(record.state==='generating'){const elapsed=(now-Date.parse(record.state_since))/1000;$('live-state-'+agent).textContent=`Generating response · ${duration(elapsed)} elapsed`;}}}
 setInterval(tick,1000);
 return {render};
})();
